const normalizeUrl = (value) => {
  if (!value) return '';
  return String(value)
    .trim()
    .split('#')[0]
    .split('?')[0]
    .replace(/^http:\/\//i, 'https://')
    .replace(/\/+$/, '')
    .toLowerCase();
};

const normalizeQuery = (value) => String(value || '')
  .trim()
  .toLowerCase()
  .replace(/ё/g, 'е')
  .replace(/\s+/g, ' ');

const shortUrl = (url) => normalizeUrl(url).replace('https://boosterpro.ru', '') || '/';

const pageType = (url) => {
  const u = normalizeUrl(url);
  if (u.includes('/collection/')) return 'CATEGORY';
  if (u.includes('/product/')) return 'PRODUCT';
  if (u.includes('/blogs/')) return 'ARTICLE';
  return 'OTHER';
};

const boolVal = (v, fallback = true) => {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  return !['false','0','no','off','нет'].includes(s);
};

const num = (v) => {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
};

const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

const collectGscRows = (nodeName) => {
  const rows = [];
  let error = '';
  let pages = 0;
  try {
    const items = $(nodeName).all();
    pages = items.length;
    for (const item of items) {
      const j = item.json || {};
      if (j.error || j.error_code || (j.statusCode && Number(j.statusCode) >= 400)) {
        error = j.error?.message || j.error_message || j.message || `HTTP ${j.statusCode}`;
      }
      const buckets = [];
      if (Array.isArray(j.rows)) buckets.push(j.rows);
      if (j.body && Array.isArray(j.body.rows)) buckets.push(j.body.rows);
      if (Array.isArray(j)) {
        for (const p of j) {
          if (p && Array.isArray(p.rows)) buckets.push(p.rows);
          if (p?.body && Array.isArray(p.body.rows)) buckets.push(p.body.rows);
        }
      }
      for (const b of buckets) rows.push(...b);
    }
  } catch (e) {
    error = e.message || String(e);
  }
  return { rows, error, pages };
};

const buildQueryMap = (rows) => {
  const map = {};
  for (const r of rows) {
    const keys = Array.isArray(r.keys) ? r.keys : [];
    const query = normalizeQuery(keys[0] || r.query || '');
    const pageRaw = keys[1] || r.page || r.url || '';
    const page = normalizeUrl(pageRaw);
    if (!query || !page) continue;

    const impressions = num(r.impressions);
    const clicks = num(r.clicks);
    const position = num(r.position);

    if (!map[query]) {
      map[query] = {
        query,
        display_query: String(keys[0] || r.query || query),
        total_impressions: 0,
        total_clicks: 0,
        pages: {}
      };
    }
    const q = map[query];
    q.total_impressions += impressions;
    q.total_clicks += clicks;

    if (!q.pages[page]) {
      q.pages[page] = {
        url: pageRaw || page,
        clean_url: page,
        impressions: 0,
        clicks: 0,
        pos_num: 0,
        pos_den: 0
      };
    }
    const p = q.pages[page];
    p.impressions += impressions;
    p.clicks += clicks;
    if (position > 0 && impressions > 0) {
      p.pos_num += position * impressions;
      p.pos_den += impressions;
    }
  }

  for (const q of Object.values(map)) {
    for (const p of Object.values(q.pages)) {
      p.position = p.pos_den > 0 ? p.pos_num / p.pos_den : 0;
      p.ctr = p.impressions > 0 ? p.clicks / p.impressions : 0;
    }
  }
  return map;
};

const aggregatePageMap = (queryMap) => {
  const out = {};
  for (const q of Object.values(queryMap)) {
    for (const p of Object.values(q.pages)) {
      const url = p.clean_url;
      if (!out[url]) out[url] = { impressions:0, clicks:0, pos_num:0, pos_den:0 };
      out[url].impressions += p.impressions;
      out[url].clicks += p.clicks;
      if (p.position > 0 && p.impressions > 0) {
        out[url].pos_num += p.position * p.impressions;
        out[url].pos_den += p.impressions;
      }
    }
  }
  for (const o of Object.values(out)) {
    o.position = o.pos_den ? o.pos_num / o.pos_den : 0;
    o.ctr = o.impressions ? o.clicks / o.impressions : 0;
  }
  return out;
};

const getPage = (queryMap, query, url) => {
  const q = queryMap[query];
  if (!q) return { impressions:0, clicks:0, position:0, ctr:0 };
  return q.pages[normalizeUrl(url)] || { impressions:0, clicks:0, position:0, ctr:0 };
};

const addMetrics = (target, source) => {
  target.impressions += num(source.impressions);
  target.clicks += num(source.clicks);
  if (num(source.position) > 0 && num(source.impressions) > 0) {
    target.pos_num += num(source.position) * num(source.impressions);
    target.pos_den += num(source.impressions);
  }
};

const finalizeMetrics = (x) => ({
  impressions: Math.round(x.impressions),
  clicks: Math.round(x.clicks),
  position: x.pos_den > 0 ? x.pos_num / x.pos_den : 0,
  ctr: x.impressions > 0 ? x.clicks / x.impressions : 0
});

const parseYandexQueryAnalytics = (nodeName) => {
  const out = {};
  let error = '';
  let pages = 0;
  try {
    const items = $(nodeName).all();
    pages = items.length;
    const records = [];
    for (const item of items) {
      const j = item.json || {};
      if (j.error_code || j.error || (j.statusCode && Number(j.statusCode) >= 400)) {
        error = j.error_message || j.message || j.error?.message || `HTTP ${j.statusCode}`;
      }
      if (Array.isArray(j.text_indicator_to_statistics)) records.push(...j.text_indicator_to_statistics);
      if (j.body && Array.isArray(j.body.text_indicator_to_statistics)) records.push(...j.body.text_indicator_to_statistics);
    }

    for (const rec of records) {
      const query = normalizeQuery(rec?.text_indicator?.type === 'QUERY' ? rec.text_indicator.value : '');
      if (!query) continue;
      const topUrl = rec?.popular_complementary_indicator?.type === 'URL'
        ? normalizeUrl(rec.popular_complementary_indicator.value)
        : '';
      const byDate = {};
      for (const s of (rec.statistics || [])) {
        const date = String(s.date || '');
        if (!byDate[date]) byDate[date] = {};
        byDate[date][String(s.field || '').toUpperCase()] = num(s.value);
      }

      let impressions = 0, clicks = 0, posNum = 0, posDen = 0;
      for (const d of Object.values(byDate)) {
        const imp = num(d.IMPRESSIONS);
        const clk = num(d.CLICKS);
        const pos = num(d.POSITION);
        impressions += imp;
        clicks += clk;
        if (pos > 0 && imp > 0) {
          posNum += pos * imp;
          posDen += imp;
        }
      }

      out[query] = {
        query,
        top_url: topUrl,
        impressions,
        clicks,
        position: posDen ? posNum / posDen : 0
      };
    }
  } catch (e) {
    error = e.message || String(e);
  }
  return { map: out, error, pages };
};

