  `GSCprev28 ${dataQuality.gsc_previous_28_ok ? 'OK' : 'WARN'}:${dataQuality.gsc_previous_28_rows}; ` +
  `GSC7 ${dataQuality.gsc_current_7_ok ? 'OK' : 'WARN'}:${dataQuality.gsc_current_7_rows}; ` +
  `YandexQuery ${dataQuality.yandex_query_ok ? 'OK' : 'WARN'}:${dataQuality.yandex_query_rows}; ` +
  `Metrika ${dataQuality.yandex_metrika_ok ? 'OK' : 'WARN'}; ` +
  `SERP effective ${dataQuality.serp_state_rows} rows; live ${Number(liveSerpMeta.serpapi_searches||0)} searches`;

const today = new Date().toISOString().split('T')[0];

if (!dataQuality.gsc_current_28_ok) {
  const prompt = `Сформируй короткое сообщение: анализ каннибализации не выполнен, потому что текущий 28-дневный GSC query+page не вернул валидные данные. Не делай SEO-выводов. Data Quality: ${JSON.stringify(dataQuality)}`;
  return [{
    json: {
      report_date: today,
    run_mode: runMode,
    snapshot_id: snapshotId,
    gsc_data_end: gscDataEnd,
    yandex_query_data_end: yandexQueryDataEnd,
    page_snapshot_id: pageSnapshotId,
      fatal_data_error: true,
      data_quality: dataQuality,
      data_quality_text: dataQualityText,
      categories_health: [],
      active_incidents: [],
      low_data_incidents: [],
      resolved_incidents: [],
      history_rows: [],
      state_rows: [],
      discovery_rows: [],
      primary_query_checks: [],
      primary_check_counts: {tracked:0,owner_ok:0,mismatch_confirmed:0,mixed:0,mismatch_other:0,not_found:0,data_error:0,intent_ambiguous:0},
      serp_policy: { mode:String(liveSerpMeta.live_mode||'ALL_PRIMARY_TTL'), max_live_queries:Number(liveSerpMeta.max_live_queries||32), cache_ttl_days:Number(liveSerpMeta.cache_ttl_days||14), max_age_days:Number(liveSerpMeta.evidence_max_age_days||45), live_api_calls:Number(liveSerpMeta.serpapi_searches||0), live_queries_attempted:Number(liveSerpMeta.live_queries_attempted||0), live_queries_successful:Number(liveSerpMeta.live_queries_successful||0), live_data_errors:Number(liveSerpMeta.live_data_errors||0) },
      prompt_for_ai: prompt,
      counts: { critical:0, high:0, watch:0, low_data:0, resolved:0, new:0, worsening:0 }
    }
  }];
}

// ----- URL maps / briefs / redirects -----
const activeTargets = new Set();
const targetCategories = [];
const redirectMap = {};
const titleMap = {};

for (const r of monitorRows) {
  const url = normalizeUrl(r.url);
  if (!url) continue;
  const type = String(r.type || 'target').toLowerCase();
  const active = boolVal(r.active, true);
  const expectedStatus = Number(r.expected_status || 0);
  if (type === 'redirect' || expectedStatus === 301) {
    redirectMap[url] = normalizeUrl(r.expected_target || r.redirect_target || '');
  } else if (active && expectedStatus === 200) {
    // V2.1 SCOPE: only pages explicitly monitored as 200 in Daily_Monitor are owners/report targets.
    activeTargets.add(url);
    titleMap[url] = r.expected_h1 || url.split('/').pop();
    if ((r.group || '') === 'Categories' || url.includes('/collection/')) targetCategories.push(url);
  }
}

// Manual SEO Change Log context for cannibalization. It never changes severity; it only prevents repeating already-applied advice.
const parseChangeDate=raw=>{if(raw===undefined||raw===null||String(raw).trim()==='')return '';const n=Number(raw);let d=null;if(Number.isFinite(n)&&n>30000&&n<70000)d=new Date(Date.UTC(1899,11,30)+n*86400000);else{const s=String(raw).trim().split('T')[0].split(' ')[0];let m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(m)d=new Date(Date.UTC(+m[1],+m[2]-1,+m[3]));m=s.match(/^(\d{2})[./](\d{2})[./](\d{4})$/);if(!d&&m)d=new Date(Date.UTC(+m[3],+m[2]-1,+m[1]));}return d&&!Number.isNaN(d.getTime())?isoDate(d):'';};
const isWatchChange=v=>['WATCH','ACTIVE','OBSERVE','НАБЛЮДАЕМ','НАБЛЮДАТЬ','АКТИВНО'].includes(String(v||'WATCH').trim().toUpperCase());
const watchChangesByUrl={};
for(let i=0;i<seoChangeRows.length;i++){
  const r=seoChangeRows[i]||{};const u=normalizeUrl(r.url||r.page||r.page_url);const dt=parseChangeDate(r.change_date||r.date||r.changed_at);if(!u||!dt||!isWatchChange(r.tracking_status||r.status))continue;
  if(!watchChangesByUrl[u])watchChangesByUrl[u]=[];
  watchChangesByUrl[u].push({change_id:String(r.change_id||`CHG-${dt}-${i+1}`),change_date:dt,change_type:String(r.change_type||r.type||'other'),what_changed:String(r.what_changed||r.changes||r.description||''),hypothesis:String(r.hypothesis||'')});
}
for(const arr of Object.values(watchChangesByUrl))arr.sort((a,b)=>b.change_date.localeCompare(a.change_date));

const briefByUrl = {};
const pageIdToUrl = {};
for (const r of briefRows) {
  const slug = String(r.slug || '').trim();
  const url = slug ? normalizeUrl(`https://boosterpro.ru/collection/${slug}`) : '';
  if (!url) continue;
  briefByUrl[url] = {
    page_id: r.page_id || '',
    category: r.category || '',
    primary_query: r.primary_query || '',
    boundaries: r['intent_boundaries (Запреты)'] || r.intent_boundaries || '',
    model_rules: r['model_rules (Модели и факты)'] || '',
    h2: r['h2_structure (Обязательные блоки)'] || ''
  };
  if (r.page_id) pageIdToUrl[String(r.page_id).trim().toUpperCase()] = url;
  titleMap[url] = r.category || titleMap[url] || slug;
}

// ----- v2.17 Primary Query + effective SERP evidence (cache + tiny live overlay) -----
// Master_Briefs.primary_query is a high-confidence CONTROL owner, but it does NOT
// change the existing risk_score/severity formula. Owner_Map remains the only source
// of scored clusters. Live SERP is evidence only; it never adds score points.
const primaryQueryOwners = {};
for (const [url, b] of Object.entries(briefByUrl)) {
  const query = normalizeQuery(b.primary_query);
  if (!query || !activeTargets.has(url)) continue;
  primaryQueryOwners[query] = {
    query,
    display_query: String(b.primary_query || query),
    owner_url: url,
    category: b.category || titleMap[url] || shortUrl(url),
    slug: shortUrl(url).split('/').filter(Boolean).pop() || ''
  };
}
dataQuality.primary_query_rows = Object.keys(primaryQueryOwners).length;

const SERP_MAX_AGE_DAYS = Number(liveSerpMeta.evidence_max_age_days || 45);
const dayMs = 86400000;
const parseSerpDate = (value) => {
  const d = new Date(String(value || ''));
  return Number.isNaN(d.getTime()) ? null : d;
};
const serpByQuery = {};
for (const r of serpStateRows) {
  const query = normalizeQuery(r.query || '');
  const engine = String(r.engine || '').trim().toLowerCase();
  if (!query || !['google','yandex'].includes(engine)) continue;
  const dt = parseSerpDate(r.checked_at);
  if (!dt) continue;
  const source = String(r._serp_source || r.source || 'CACHE').toUpperCase() === 'LIVE' ? 'LIVE' : 'CACHE';
  const ageDays = source === 'LIVE' ? 0 : Math.floor((nowDate.getTime() - dt.getTime()) / dayMs);
  if (source !== 'LIVE' && (ageDays < -1 || ageDays > SERP_MAX_AGE_DAYS)) continue;
  if (!serpByQuery[query]) serpByQuery[query] = {};
  const prev = serpByQuery[query][engine];
  const prevDt = prev ? parseSerpDate(prev.checked_at) : null;
  if (!prev || source === 'LIVE' || !prevDt || dt > prevDt) {
    serpByQuery[query][engine] = {
      engine,
      checked_at: String(r.checked_at || ''),
      age_days: ageDays,
      source,
      found: boolVal(r.found, false),
      rank: num(r.rank),
      result_url: normalizeUrl(r.result_url || ''),
      owner_match: boolVal(r.owner_match, false),
      status: String(r.status || ''),
      data_error: boolVal(r.data_error, false),
      error: String(r.error || '')
    };
  }
}
dataQuality.serp_fresh_rows = Object.values(serpByQuery).reduce((s,x)=>s+Object.keys(x).length,0);
dataQuality.serp_tracked_primary_queries = Object.keys(primaryQueryOwners).filter(q=>serpByQuery[q]&&Object.keys(serpByQuery[q]).length).length;

const buildSerpEvidence = (queryList, ownerUrl, competitorUrl='') => {
  const owner = normalizeUrl(ownerUrl);
  const competitor = normalizeUrl(competitorUrl);
  const details = [];
  const seen = new Set();
  for (const qRaw of queryList || []) {
    const q = normalizeQuery(typeof qRaw === 'string' ? qRaw : (qRaw.query_key || qRaw.query || ''));
    if (!q || seen.has(q)) continue;
    seen.add(q);
    const rows = serpByQuery[q] || {};
    for (const engine of ['google','yandex']) {
      const r = rows[engine];
      if (!r) continue;
      let relation = 'NOT_FOUND';
      if (r.data_error) relation = 'DATA_ERROR';
      else if (r.found && r.result_url) {
        if (r.result_url === owner) relation = 'OWNER';
        else if (competitor && r.result_url === competitor) relation = 'COMPETITOR';
        else relation = 'OTHER_URL';
      }
      details.push({ query:q, engine, relation, rank:r.rank, result_url:r.result_url, status:r.status, checked_at:r.checked_at, age_days:r.age_days, source:r.source, data_error:r.data_error, error:r.error });
    }
  }
  if (!details.length) return {status:'NO_SERP_DATA', details:[], confirming_engines:[], owner_engines:[], other_engines:[], not_found_engines:[], data_error_engines:[]};
  const valid = details.filter(x=>x.relation!=='DATA_ERROR');
  const confirming = valid.filter(x=>x.relation==='COMPETITOR').map(x=>x.engine);
  const ownerEng = valid.filter(x=>x.relation==='OWNER').map(x=>x.engine);
  const otherEng = valid.filter(x=>x.relation==='OTHER_URL').map(x=>x.engine);
  const notFound = valid.filter(x=>x.relation==='NOT_FOUND').map(x=>x.engine);
  const dataErrors = details.filter(x=>x.relation==='DATA_ERROR').map(x=>x.engine);
  let status = 'SERP_OTHER';
  if (!valid.length && dataErrors.length) status = 'DATA_ERROR';
  else if (confirming.length && ownerEng.length) status = 'MIXED';
  else if (confirming.length) status = 'CONFIRMS_CONFLICT';
  else if (ownerEng.length && otherEng.length) status = 'MIXED';
  else if (ownerEng.length && !otherEng.length) status = 'OWNER_CONFIRMS';
  else if (otherEng.length) status = 'OTHER_ALT_URL';
  else if (notFound.length) status = 'NOT_FOUND_TOP10';
  return {status, details, confirming_engines:[...new Set(confirming)], owner_engines:[...new Set(ownerEng)], other_engines:[...new Set(otherEng)], not_found_engines:[...new Set(notFound)], data_error_engines:[...new Set(dataErrors)]};
};

// Primary controls are reported separately from scored Owner_Map incidents.
// Use effective SERP evidence: fresh LIVE rows override CACHE rows for this run.
const primaryQueryChecks = [];
for (const [query, p] of Object.entries(primaryQueryOwners)) {
  if (!serpByQuery[query] || !Object.keys(serpByQuery[query]).length) continue;
  const q = current28[query];
  const pages = q ? Object.values(q.pages).sort((a,b)=>b.impressions-a.impressions || b.clicks-a.clicks) : [];
  const top = pages[0] || null;
  const ownerMetric = getPage(current28, query, p.owner_url);
  const gscTopUrl = top ? top.clean_url : '';
  const gscOwnerMatch = !!gscTopUrl && gscTopUrl === p.owner_url;
  const competitorUrl = gscTopUrl && gscTopUrl !== p.owner_url ? gscTopUrl : '';
  const serp = buildSerpEvidence([query], p.owner_url, competitorUrl);
  const validDetails = serp.details.filter(x=>x.relation!=='DATA_ERROR');
  const serpHasOwner = validDetails.some(x=>x.relation==='OWNER');
  const serpHasCompetitor = validDetails.some(x=>x.relation==='COMPETITOR');
  const serpHasAlt = validDetails.some(x=>['COMPETITOR','OTHER_URL'].includes(x.relation));
  const serpHasNotFound = validDetails.some(x=>x.relation==='NOT_FOUND');
  const serpHasDataError = serp.details.some(x=>x.relation==='DATA_ERROR');
  const isBranded = /(^|\s)booster(\s|$)/i.test(String(p.display_query||query));
  const homeUrl = normalizeUrl('https://boosterpro.ru/');
  const hasAmbiguousBrandAlt = isBranded && (
    gscTopUrl === homeUrl ||
    validDetails.some(x=>x.result_url===homeUrl || pageType(x.result_url)==='PRODUCT')
  );
  let evidenceStatus = 'NO_SERP_DATA';
  if (hasAmbiguousBrandAlt && (gscTopUrl && !gscOwnerMatch || serpHasAlt)) evidenceStatus = 'INTENT_AMBIGUOUS';
  // If at least one engine shows the expected owner while another engine/history shows a different URL,
  // this is a mixed signal, not a confirmed conflict.
  else if ((serpHasOwner && serpHasAlt) || (gscTopUrl && !gscOwnerMatch && serpHasOwner)) evidenceStatus = 'MIXED';
  else if (gscTopUrl && !gscOwnerMatch && serpHasCompetitor) evidenceStatus = 'CONFIRMS_CONFLICT';
  else if (gscOwnerMatch && serpHasOwner && !serpHasAlt) evidenceStatus = 'OWNER_CONFIRMED';
  else if (!gscTopUrl && serpHasOwner && !serpHasAlt) evidenceStatus = 'OWNER_CONFIRMED';
  else if (serpHasAlt) evidenceStatus = 'SERP_ONLY';
  else if (validDetails.length && validDetails.every(x=>x.relation==='NOT_FOUND')) evidenceStatus = 'NOT_FOUND_TOP10';
  else if (!validDetails.length && serpHasDataError) evidenceStatus = 'DATA_ERROR';
  else if (serpHasNotFound) evidenceStatus = 'NOT_FOUND_TOP10';
  else if (gscTopUrl && !gscOwnerMatch) evidenceStatus = 'NO_SERP_DATA';
  primaryQueryChecks.push({
    query,
    display_query:p.display_query,
    category:p.category,
    owner_url:p.owner_url,
    gsc_impressions_28d:q ? Math.round(q.total_impressions) : 0,
    gsc_clicks_28d:q ? Math.round(q.total_clicks) : 0,
    gsc_top_url:gscTopUrl,
    gsc_top_position:top ? Number((top.position||0).toFixed(2)) : 0,
    gsc_top_impressions:top ? Math.round(top.impressions||0) : 0,
    gsc_owner_impressions:Math.round(ownerMetric.impressions||0),
    gsc_owner_position:Number((ownerMetric.position||0).toFixed(2)),
    gsc_owner_match:gscOwnerMatch,
    status:evidenceStatus,
    evidence_status:evidenceStatus,
    serp_status:serp.status,
    serp_evidence:serp.details
  });
}
const primaryCheckCounts = {
  tracked: primaryQueryChecks.length,
  owner_ok: primaryQueryChecks.filter(x=>x.status==='OWNER_CONFIRMED').length,
  mismatch_confirmed: primaryQueryChecks.filter(x=>x.status==='CONFIRMS_CONFLICT').length,
  mixed: primaryQueryChecks.filter(x=>x.status==='MIXED').length,
  mismatch_other: primaryQueryChecks.filter(x=>x.status==='SERP_ONLY').length,
  not_found: primaryQueryChecks.filter(x=>x.status==='NOT_FOUND_TOP10').length,
  data_error: primaryQueryChecks.filter(x=>x.status==='DATA_ERROR').length,
  intent_ambiguous: primaryQueryChecks.filter(x=>x.status==='INTENT_AMBIGUOUS').length
};

// Baseline monthly norm
const baselineMap = {};
for (const r of baselineRows) {
  const url = normalizeUrl(r.url);
  if (!url) continue;
  baselineMap[url] = {
    visits: Math.round(num(r.search_visits_base) / 12),
    clicks: Math.round(num(r.google_clicks_base) / 12),
    impressions: Math.round(num(r.google_impressions_base) / 12),
    bounce: num(r.bounce_rate_base),
    time: num(r.time_on_site_base_sec),
    depth: num(r.page_depth_base)
  };
}

// ----- Owner Map -----
const slugify = (s) => normalizeQuery(s)
  .replace(/[^a-zа-я0-9]+/gi, '_')
  .replace(/^_+|_+$/g, '')
  .slice(0, 80);

const ownerMap = {};
const clusterMeta = {};
for (const r of ownerRows) {
  if (!boolVal(r.active, true)) continue;
  const query = normalizeQuery(r.query);
  const owner = normalizeUrl(r.owner_url);
  if (!query || !owner) continue;
  // V2.1 SCOPE: ignore Owner_Map rules whose owner is not an active 200 page from Daily_Monitor.
  // Competitors may still be any BoosterPro URL if they steal visibility from a monitored owner.
  if (!activeTargets.has(owner)) continue;

  const cluster = String(r.cluster || 'Без кластера').trim();
  const clusterId = String(r.cluster_id || '').trim() || slugify(`${cluster}_${shortUrl(owner)}`);
  const allowedSecondary = String(r.allowed_secondary_urls || '')
    .split(',')
    .map(normalizeUrl)
    .filter(Boolean);

  const forbiddenIds = String(r.forbidden_pages || '')
    .match(/C\d{3}/gi) || [];
  const forbiddenUrls = forbiddenIds
    .map(id => pageIdToUrl[id.toUpperCase()])
    .filter(Boolean);

  ownerMap[query] = {
    query,
    display_query: String(r.query || query),
    owner_url: owner,
    cluster,
    cluster_id: clusterId,
    rule: r.rule || '',
    priority: num(r.priority) || 1,
    match_mode: r.match_mode || 'EXACT',
    allowed_secondary_urls: new Set(allowedSecondary),
    forbidden_urls: new Set(forbiddenUrls),
    source: 'OWNER_MAP',
    is_primary_query: !!(primaryQueryOwners[query] && primaryQueryOwners[query].owner_url === owner)
  };

  if (!clusterMeta[clusterId]) {
    clusterMeta[clusterId] = {
      cluster_id: clusterId,
      cluster,
      owners: {},
      queries: []
    };
  }
  clusterMeta[clusterId].owners[owner] = (clusterMeta[clusterId].owners[owner] || 0) + 1;
  clusterMeta[clusterId].queries.push(query);
}
// Show the scoped Owner_Map size, not the whole sheet size.
dataQuality.owner_map_rows = Object.keys(ownerMap).length;

// ----- Previous state -----
const prevState = {};
const prevStateByPair = {};
const pairKey = (cluster,owner,competitor) => `${normalizeQuery(cluster)}|${shortUrl(owner)}|${shortUrl(competitor)}`;
for (const r of stateRows) {
  const key = String(r.incident_key || '').trim();
  if (key) prevState[key] = r;
  if (r.owner_url && r.competitor_url) prevStateByPair[pairKey(r.cluster||r.cluster_id||'',r.owner_url,r.competitor_url)] = r;
}
// History is only a fallback when State was reset or incident_key schema changed.
for (const r of historyStateRows) {
  if (!r.owner_url || !r.competitor_url) continue;
  const pk=pairKey(r.cluster||r.cluster_id||'',r.owner_url,r.competitor_url);
  const cur=prevStateByPair[pk];
  const ru=String(r.updated_at||''); const cu=String(cur?.updated_at||'');
  if (!cur || ru>cu) prevStateByPair[pk]=r;
}

const inferIncidentType = (owner, competitor) => {
  if (redirectMap[competitor]) return 'LEGACY_REDIRECT';
  const ot = pageType(owner);
  const ct = pageType(competitor);
  if (ot === 'CATEGORY' && ct === 'CATEGORY') return 'SIBLING_CATEGORY';
  if (ot === 'CATEGORY' && ct === 'PRODUCT') return 'PRODUCT_OVER_CATEGORY';
  if (ot === 'CATEGORY' && ct === 'ARTICLE') return 'ARTICLE_OVER_CATEGORY';
  if (ot === 'ARTICLE' && ct === 'CATEGORY') return 'CATEGORY_OVER_ARTICLE';
  if (ot === 'ARTICLE' && ct === 'ARTICLE') return 'ARTICLE_OVER_ARTICLE';
  if (ot === 'PRODUCT' && ct === 'CATEGORY') return 'CATEGORY_OVER_PRODUCT';
  return 'SPLIT_VISIBILITY';
};

const incidentScope = (owner, competitor) => {
  const ot = pageType(owner);
  const ct = pageType(competitor);
  return ot === 'CATEGORY' && ct === 'CATEGORY'
    ? 'INTERNAL_CATEGORY'
    : 'SITEWIDE_CROSS_TYPE';
};

const metricInit = () => ({ impressions:0, clicks:0, pos_num:0, pos_den:0 });

const groups = {};

for (const [query, cfg] of Object.entries(ownerMap)) {
  const curQ = current28[query];
  if (!curQ) continue;

  const owner = cfg.owner_url;
  const ownerNow = getPage(current28, query, owner);
  const pages = Object.values(curQ.pages);

  for (const comp of pages) {
    const competitor = comp.clean_url;
    if (!competitor || competitor === owner) continue;
    if (!competitor.includes('boosterpro.ru')) continue;
    if (cfg.allowed_secondary_urls.has(competitor)) continue;
    if (comp.impressions < 2 && comp.clicks < 1) continue;

    const key = `${cfg.cluster_id}|${shortUrl(owner)}|${shortUrl(competitor)}`;
    if (!groups[key]) {
      groups[key] = {
        incident_key: key,
        cluster_id: cfg.cluster_id,
        cluster: cfg.cluster,
        owner_url: owner,
        competitor_url: competitor,
        owner28: metricInit(),
        comp28: metricInit(),
        ownerPrev28: metricInit(),
        compPrev28: metricInit(),
        owner7: metricInit(),
        comp7: metricInit(),
        ownerPrev7: metricInit(),
        compPrev7: metricInit(),
        site_impressions_28: 0,
        queries: [],
        yandex_owner_impressions: 0,
        yandex_comp_impressions: 0,
        yandex_other_impressions: 0,
        yandex_comp_pos_num: 0,
        yandex_comp_pos_den: 0,
        forbidden_hit: false,
        rules: new Set(),
        boundaries: briefByUrl[owner]?.boundaries || '',
        contains_primary_query: false,
        owner_sources: new Set()
      };
    }

    const g = groups[key];
    addMetrics(g.owner28, ownerNow);
    addMetrics(g.comp28, comp);

    const op28 = getPage(previous28, query, owner);
    const cp28 = getPage(previous28, query, competitor);
    const oc7 = getPage(current7, query, owner);
    const cc7 = getPage(current7, query, competitor);
    const op7 = getPage(previous7, query, owner);
    const cp7 = getPage(previous7, query, competitor);

    addMetrics(g.ownerPrev28, op28);
    addMetrics(g.compPrev28, cp28);
    addMetrics(g.owner7, oc7);
    addMetrics(g.comp7, cc7);
    addMetrics(g.ownerPrev7, op7);
    addMetrics(g.compPrev7, cp7);

    g.site_impressions_28 += curQ.total_impressions;
    if (cfg.forbidden_urls.has(competitor)) g.forbidden_hit = true;
    if (cfg.rule) g.rules.add(String(cfg.rule));
    if (cfg.is_primary_query) g.contains_primary_query = true;
    g.owner_sources.add(cfg.source || 'OWNER_MAP');

    const y = yandexQuery.map[query];
    if (y && y.impressions > 0) {
      if (y.top_url === owner) g.yandex_owner_impressions += y.impressions;
      else if (y.top_url === competitor) {
        g.yandex_comp_impressions += y.impressions;
        if (y.position > 0) {
          g.yandex_comp_pos_num += y.position * y.impressions;
          g.yandex_comp_pos_den += y.impressions;
        }
      } else {
        g.yandex_other_impressions += y.impressions;
      }
    }

    g.queries.push({
      query: curQ.display_query || query,
      query_key: query,
      owner_impressions: ownerNow.impressions,
      competitor_impressions: comp.impressions,
      owner_clicks: ownerNow.clicks,
      competitor_clicks: comp.clicks,
      owner_position: ownerNow.position,
      competitor_position: comp.position,
      total_site_impressions: curQ.total_impressions,
      is_primary_query: !!cfg.is_primary_query,
      owner_source: cfg.source || 'OWNER_MAP'
    });
  }
}

const ratio = (current, previous) => {
  if (previous <= 0) return current > 0 ? null : 1;
  return current / previous;
};

const share = (a, b) => (a + b) > 0 ? a / (a + b) : 0;

const severityRank = { CRITICAL:4, HIGH:3, WATCH:2, LOW_DATA:1, OK:0 };

const activeIncidents = [];
const lowDataIncidents = [];
const historyRows = [];
const stateOutput = [];
const activeKeys = new Set();

for (const g of Object.values(groups)) {
  const o28 = finalizeMetrics(g.owner28);
  const c28 = finalizeMetrics(g.comp28);
  const op28 = finalizeMetrics(g.ownerPrev28);
  const cp28 = finalizeMetrics(g.compPrev28);
  const o7 = finalizeMetrics(g.owner7);
  const c7 = finalizeMetrics(g.comp7);
  const op7 = finalizeMetrics(g.ownerPrev7);
  const cp7 = finalizeMetrics(g.compPrev7);

  const pairImp = o28.impressions + c28.impressions;
  const pairClicks = o28.clicks + c28.clicks;
  const compShare = share(c28.impressions, o28.impressions);
  const ownerShare = 1 - compShare;
  const compClickShare = share(c28.clicks, o28.clicks);

  const prevPairShare = share(cp28.impressions, op28.impressions);
  const current7Share = share(c7.impressions, o7.impressions);
  const prev7Share = share(cp7.impressions, op7.impressions);

  const owner28Ratio = ratio(o28.impressions, op28.impressions);
  const comp28Ratio = ratio(c28.impressions, cp28.impressions);

  const prev = prevState[g.incident_key] || prevStateByPair[pairKey(g.cluster,g.owner_url,g.competitor_url)];
  const prevWasActive = prev ? boolVal(prev.active, false) : false;
  const prevRuns = prevWasActive ? Math.max(1, Math.round(num(prev.consecutive_runs))) : 0;
  const sameSnapshot = prevWasActive && String(prev.snapshot_id||'') === snapshotId;
  const consecutiveRuns = prevWasActive ? (sameSnapshot ? prevRuns : prevRuns + 1) : 1;
  const previousScore = prev ? num(prev.risk_score) : 0;

  // 1) Dominance: 0..25
  const dominanceScore = compShare <= 0.35 ? 0 : clamp((compShare - 0.35) / 0.55 * 25, 0, 25);

  // 2) Position displacement: 0..20
  let positionScore = 0;
  if (o28.position > 0 && c28.position > 0) {
    positionScore = clamp((o28.position - c28.position) / 15 * 20, 0, 20);
  } else if (o28.impressions === 0 && c28.position > 0) {
    positionScore = c28.position <= 20 ? 20 : (c28.position <= 40 ? 12 : 6);
  }

  // 3) Click capture: 0..15
  let clickScore = 0;
  if (pairClicks >= 2) clickScore = clamp((compClickShare - 0.30) / 0.70 * 15, 0, 15);
  else if (c28.clicks > 0 && o28.clicks === 0) clickScore = 8;

  // 4) Period trend: 0..20
  let trendScore = 0;
  if (owner28Ratio !== null && comp28Ratio !== null) {
    if (owner28Ratio <= 0.75 && comp28Ratio >= 1.25) trendScore += 12;
    else if (owner28Ratio <= 0.90 && comp28Ratio >= 1.10) trendScore += 8;
    else if (owner28Ratio <= 0.75 && comp28Ratio >= 0.90) trendScore += 5;
  } else if (op28.impressions === 0 && cp28.impressions === 0 && c28.impressions >= 20 && o28.impressions === 0) {
    trendScore += 6;
  }
  const shareDelta7 = current7Share - prev7Share;
  if (dataQuality.gsc_current_7_ok && dataQuality.gsc_previous_7_ok) {
    if (shareDelta7 >= 0.15) trendScore += 8;
    else if (shareDelta7 >= 0.05) trendScore += 4;
  }
  trendScore = clamp(trendScore, 0, 20);

  // 5) Structural mismatch: 0..10
  const incidentBaseType = inferIncidentType(g.owner_url, g.competitor_url);
  let structuralScore = 0;
  if (o28.impressions === 0 && c28.impressions >= 10) structuralScore = 10;
  else if (g.forbidden_hit) structuralScore = 10;
  else if (incidentBaseType === 'LEGACY_REDIRECT') structuralScore = 10;
  else if (incidentBaseType !== 'SPLIT_VISIBILITY') structuralScore = 7;
  else structuralScore = 3;

  // 6) Persistence: 0..10
  const persistenceScore = prevRuns >= 3 ? 10 : (prevRuns >= 2 ? 7 : (prevRuns >= 1 ? 4 : 0));

  const rawScore = clamp(
    dominanceScore + positionScore + clickScore + trendScore + structuralScore + persistenceScore,
    0, 100
  );

  let confidence = pairImp >= 300 ? 0.95 :
                   pairImp >= 100 ? 0.85 :
                   pairImp >= 30  ? 0.70 :
                   pairImp >= 10  ? 0.50 : 0.30;
  if (g.queries.length >= 3) confidence += 0.05;
  if (pairClicks >= 5) confidence += 0.05;
  if (g.yandex_comp_impressions >= 10) confidence += 0.05;
  confidence = clamp(confidence, 0.25, 1.0);

  const riskScore = Math.round(rawScore * confidence);

  let severity = 'OK';
  if (pairImp < 10 && pairClicks < 2) severity = 'LOW_DATA';
  else if (riskScore >= 75 && compShare >= 0.65 && (consecutiveRuns >= 2 || pairImp >= 200)) severity = 'CRITICAL';
  else if (riskScore >= 55) severity = 'HIGH';
  else if (riskScore >= 30) severity = 'WATCH';

  // If last run was active, don't silently drop to LOW_DATA while competitor is still present.
  if (prevWasActive && severity === 'LOW_DATA' && c28.impressions > 0) severity = 'WATCH';

  let lifecycle = 'NEW';
  if (prevWasActive) {
    if (sameSnapshot) lifecycle = 'PERSISTING';
    else
    if (riskScore >= previousScore + 10) lifecycle = 'WORSENING';
    else if (riskScore <= previousScore - 10) lifecycle = 'IMPROVING';
    else lifecycle = 'PERSISTING';
  }

  let trend = 'STABLE';
  if (shareDelta7 >= 0.10) trend = 'WORSENING';
  else if (shareDelta7 <= -0.10) trend = 'IMPROVING';
  else if (owner28Ratio !== null && comp28Ratio !== null && owner28Ratio <= 0.75 && comp28Ratio >= 1.25) trend = 'WORSENING';
  else if (owner28Ratio !== null && comp28Ratio !== null && owner28Ratio >= 1.20 && comp28Ratio <= 0.85) trend = 'IMPROVING';

  const confidenceLabel = confidence >= 0.80 ? 'HIGH' : (confidence >= 0.60 ? 'MEDIUM' : 'LOW');

  let incidentType = incidentBaseType;
  if (o28.impressions === 0 && c28.impressions >= 10) incidentType = `OWNER_MISSING / ${incidentBaseType}`;

  let diagnosis = '';
  let nextCheck = '';
  if (incidentBaseType === 'LEGACY_REDIRECT') {
    diagnosis = 'Старый URL с редиректом продолжает получать поисковую видимость. Это сигнал переобхода/склейки, а не повод переписывать контент.';
    nextCheck = 'Проверить фактический 301, canonical, sitemap и внутренние ссылки на старый URL; затем наблюдать следующий срез.';
  } else if (incidentBaseType === 'SIBLING_CATEGORY') {
    diagnosis = o28.impressions === 0
      ? 'Соседняя категория ранжируется по кластеру, а назначенный owner практически отсутствует.'
      : 'Видимость кластера распределяется между двумя категориями, при этом competitor получает более сильный сигнал.';
    nextCheck = 'Сверить Title/H1/H2, границы интента из Master_Briefs и внутренние анкоры обеих категорий. Менять текст только после подтверждения конкретного пересечения.';
  } else if (incidentBaseType === 'PRODUCT_OVER_CATEGORY') {
    diagnosis = 'Карточка товара перехватывает запрос, назначенный категории.';
    nextCheck = 'Проверить анкоры на карточку и категорию, хлебные крошки, блоки рекомендаций и соответствие коммерческого интента; не удалять фразу автоматически.';
  } else if (incidentBaseType === 'ARTICLE_OVER_CATEGORY') {
    diagnosis = 'Информационная страница конкурирует с коммерческой категорией по одному кластеру.';
    nextCheck = 'Сверить интент запроса, Title/H1 статьи, коммерческие анкоры и перелинковку на категорию. Возможна нормальная смешанная выдача — сначала подтвердить.';
  } else if (incidentBaseType === 'CATEGORY_OVER_ARTICLE' || incidentBaseType === 'ARTICLE_OVER_ARTICLE') {
    diagnosis = 'Контентные URL делят один поисковый интент.';
    nextCheck = 'Сверить задачи материалов, Title/H1 и внутренние анкоры; при необходимости развести информационный и коммерческий интент.';
  } else {
    diagnosis = 'Запрос распределен между несколькими URL сайта; текущих данных недостаточно, чтобы считать это автоматической каннибализацией.';
    nextCheck = 'Проверить SERP и структуру внутренних ссылок. Не вносить контентные правки только по факту второго URL.';
  }

  const ownerPageCtx=pageContextByUrl[g.owner_url]||{};
  if (incidentBaseType==='SIBLING_CATEGORY' && ownerPageCtx.g_imp !== undefined) {
    diagnosis += ` Page-level контекст owner: ${Math.round(num(ownerPageCtx.g_imp))} Google показов / ${Math.round(num(ownerPageCtx.g_clicks))} кликов за 30д, Яндекс ${Math.round(num(ownerPageCtx.yandex))} визитов. Отсутствие относится именно к закрепленному query-кластеру, а не ко всей странице.`;
  }

  const yandexSignal =
    g.yandex_comp_impressions >= 10 ? 'COMPETITOR_CONFIRMS' :
    g.yandex_owner_impressions >= 10 ? 'OWNER_CONFIRMS' :
    (g.yandex_comp_impressions + g.yandex_owner_impressions + g.yandex_other_impressions > 0 ? 'MIXED/LOW_DATA' : 'NO_DATA');

  const queryExamples = [...g.queries]
    .sort((a,b) => b.competitor_impressions - a.competitor_impressions)
    .slice(0, 8);

  const serpEvidence = buildSerpEvidence(g.queries, g.owner_url, g.competitor_url);
  if (serpEvidence.status === 'CONFIRMS_CONFLICT') {
    diagnosis += ' Кэшированный SERP spot-check подтверждает тот же competitor хотя бы в одном поисковике; score и severity при этом не повышаются.';
  } else if (serpEvidence.status === 'MIXED') {
    diagnosis += ' SERP spot-check смешанный: поисковики/срезы показывают разные URL; это контекст, а не основание повышать severity.';
  } else if (serpEvidence.status === 'OWNER_CONFIRMS') {
    diagnosis += ' Свежий кэшированный SERP spot-check показывает назначенный owner; исторический конфликт оценивается отдельно по GSC/Yandex Query.';
  }

  const record = {
    incident_key: g.incident_key,
    active: ['CRITICAL','HIGH','WATCH'].includes(severity),
    first_seen: prev?.first_seen || today,
    last_seen: today,
    resolved_date: '',
    consecutive_runs: consecutiveRuns,
    cluster_id: g.cluster_id,
    cluster: g.cluster,
    owner_url: g.owner_url,
    competitor_url: g.competitor_url,
    owner_name: titleMap[g.owner_url] || shortUrl(g.owner_url),
    competitor_name: titleMap[g.competitor_url] || shortUrl(g.competitor_url),
    incident_type: incidentType,
    conflict_scope: incidentScope(g.owner_url, g.competitor_url),
    owner_page_type: pageType(g.owner_url),
    competitor_page_type: pageType(g.competitor_url),
    severity,
    risk_score: riskScore,
    raw_score: Math.round(rawScore),
    confidence: confidenceLabel,
    confidence_value: Number(confidence.toFixed(2)),
    lifecycle,
    trend,
    query_count: g.queries.length,
    query_examples: queryExamples.map(q => q.query).join(' || '),
    query_evidence: queryExamples,
    contains_primary_query: !!g.contains_primary_query,
    owner_source: [...g.owner_sources].join(' + ') || 'OWNER_MAP',
    serp_evidence_status: serpEvidence.status,
    serp_confirming_engines: serpEvidence.confirming_engines,
    serp_owner_engines: serpEvidence.owner_engines,
    serp_other_engines: serpEvidence.other_engines,
    serp_not_found_engines: serpEvidence.not_found_engines,
    serp_evidence: serpEvidence.details,
    owner_impressions_28d: o28.impressions,
    competitor_impressions_28d: c28.impressions,
    owner_clicks_28d: o28.clicks,
    competitor_clicks_28d: c28.clicks,
    owner_position_28d: Number(o28.position.toFixed(2)),
    competitor_position_28d: Number(c28.position.toFixed(2)),
    owner_share_pct: Number((ownerShare * 100).toFixed(1)),
    competitor_share_pct: Number((compShare * 100).toFixed(1)),
    owner_impressions_prev28: op28.impressions,
    competitor_impressions_prev28: cp28.impressions,
    owner_impressions_7d: o7.impressions,
    competitor_impressions_7d: c7.impressions,
    owner_impressions_prev7: op7.impressions,
    competitor_impressions_prev7: cp7.impressions,
    yandex_signal: yandexSignal,
    yandex_impressions_14d: Math.round(g.yandex_comp_impressions + g.yandex_owner_impressions + g.yandex_other_impressions),
    yandex_competitor_impressions_14d: Math.round(g.yandex_comp_impressions),
    yandex_competitor_position_14d: g.yandex_comp_pos_den ? Number((g.yandex_comp_pos_num / g.yandex_comp_pos_den).toFixed(2)) : 0,
    previous_score: previousScore,
    diagnosis,
    next_check: nextCheck,
    rule: [...g.rules].slice(0, 3).join(' | '),
    owner_boundaries: g.boundaries,
    data_quality: dataQualityText,
    snapshot_id: snapshotId,
    gsc_data_end: gscDataEnd,
    yandex_query_data_end: yandexQueryDataEnd,
    page_snapshot_id: pageSnapshotId,
    owner_page_status: (pageContextByUrl[g.owner_url]||{}).status || '',
    owner_page_google_impressions_30d: num((pageContextByUrl[g.owner_url]||{}).g_imp),
    owner_page_google_clicks_30d: num((pageContextByUrl[g.owner_url]||{}).g_clicks),
    owner_page_yandex_visits_30d: num((pageContextByUrl[g.owner_url]||{}).yandex),
    owner_page_google_vs_baseline_pct: (pageContextByUrl[g.owner_url]||{}).g_imp_base > 0 ? Number((num((pageContextByUrl[g.owner_url]||{}).g_imp)/num((pageContextByUrl[g.owner_url]||{}).g_imp_base)*100).toFixed(1)) : 0,
    owner_page_yandex_vs_baseline_pct: (pageContextByUrl[g.owner_url]||{}).yandex_base > 0 ? Number((num((pageContextByUrl[g.owner_url]||{}).yandex)/num((pageContextByUrl[g.owner_url]||{}).yandex_base)*100).toFixed(1)) : 0,
    updated_at: new Date().toISOString()
  };

  if (['CRITICAL','HIGH','WATCH'].includes(severity)) {
    activeIncidents.push(record);
    activeKeys.add(g.incident_key);
    stateOutput.push(record);
    historyRows.push({ check_date: today, history_key: `${snapshotId}|${record.incident_key}`, ...record });
  } else if (severity === 'LOW_DATA' && (pairImp >= 5 || c28.clicks > 0)) {
    lowDataIncidents.push(record);
  }
}

// Resolve previously active incidents only when current GSC data is healthy.
const resolvedIncidents = [];
for (const [key, prev] of Object.entries(prevState)) {
  if (!boolVal(prev.active, false)) continue;
  if (activeKeys.has(key)) continue;
  // V2.1 SCOPE: do not surface old site-wide incidents as RESOLVED if their owner is outside Daily_Monitor 200.
  if (!activeTargets.has(normalizeUrl(prev.owner_url || ''))) continue;

  const resolved = {
    incident_key: key,
    active: false,
    first_seen: prev.first_seen || today,
    last_seen: prev.last_seen || today,
    resolved_date: today,
    consecutive_runs: Math.max(1, Math.round(num(prev.consecutive_runs))),
    cluster_id: prev.cluster_id || '',
    cluster: prev.cluster || '',
    owner_url: prev.owner_url || '',
    competitor_url: prev.competitor_url || '',
    owner_name: prev.owner_name || shortUrl(prev.owner_url),
    competitor_name: prev.competitor_name || shortUrl(prev.competitor_url),
    incident_type: prev.incident_type || '',
    severity: 'RESOLVED',
    risk_score: 0,
    raw_score: 0,
    confidence: prev.confidence || '—',
    confidence_value: num(prev.confidence_value),
    lifecycle: 'RESOLVED',
    trend: 'IMPROVING',
    query_count: num(prev.query_count),
    query_examples: prev.query_examples || '',
    owner_impressions_28d: 0,
    competitor_impressions_28d: 0,
    owner_clicks_28d: 0,
    competitor_clicks_28d: 0,
    owner_position_28d: 0,
    competitor_position_28d: 0,
    owner_share_pct: 0,
    competitor_share_pct: 0,
    owner_impressions_prev28: num(prev.owner_impressions_28d),
    competitor_impressions_prev28: num(prev.competitor_impressions_28d),
    owner_impressions_7d: 0,
    competitor_impressions_7d: 0,
    owner_impressions_prev7: num(prev.owner_impressions_7d),
    competitor_impressions_prev7: num(prev.competitor_impressions_7d),
    yandex_signal: '—',
    yandex_impressions_14d: 0,
    yandex_competitor_impressions_14d: 0,
    yandex_competitor_position_14d: 0,
    previous_score: num(prev.risk_score),
    diagnosis: 'Ранее активный конфликт в текущем срезе больше не проходит порог WATCH.',
    next_check: 'Не менять страницу. Проверить ещё один недельный срез, чтобы подтвердить устойчивое разрешение.',
    rule: prev.rule || '',
    owner_boundaries: prev.owner_boundaries || '',
    data_quality: dataQualityText,
    updated_at: new Date().toISOString()
  };
  resolvedIncidents.push(resolved);
  stateOutput.push(resolved);
  historyRows.push({ check_date: today, history_key: `${snapshotId}|${resolved.incident_key}`, ...resolved });
}

// ----- Category health: same deterministic philosophy as monthly report -----
const classifyCategory = (url) => {
  const b = baselineMap[url] || { visits:0, impressions:0, clicks:0, bounce:0, time:0, depth:0 };
  const g = gscPage28[url] || { impressions:0, clicks:0, position:0 };
  const y = yandexMetrika[url] || { visits:0, bounce:0, time:0, depth:0 };

  const yRatio = b.visits > 0 ? y.visits / b.visits : 1;
  const gRatio = b.impressions > 0 ? g.impressions / b.impressions : 1;

  let status = 'GREEN';
  if (b.visits >= 30 && y.visits <= 2 && b.impressions >= 50 && g.impressions <= Math.max(10, b.impressions * 0.20)) status = 'RED';
  else if ((b.visits >= 15 && yRatio < 0.50) || (b.impressions >= 50 && gRatio < 0.50)) status = 'YELLOW';
  else if (y.visits < 10 && g.impressions < 100) status = 'LOW_DATA';

  const cannib = activeIncidents
    .filter(i => i.owner_url === url && i.conflict_scope === 'INTERNAL_CATEGORY')
    .sort((a,b) => severityRank[b.severity] - severityRank[a.severity] || b.risk_score - a.risk_score)[0];

  const sitewideOverlap = activeIncidents
    .filter(i => i.owner_url === url && i.conflict_scope === 'SITEWIDE_CROSS_TYPE')
    .sort((a,b) => severityRank[b.severity] - severityRank[a.severity] || b.risk_score - a.risk_score)[0];

  return {
    url,
    category_name: titleMap[url] || shortUrl(url),
    status,
    yandex_visits: y.visits,
    yandex_base: b.visits,
    google_impressions: Math.round(g.impressions),
    google_impressions_base: b.impressions,
    google_clicks: Math.round(g.clicks),
    google_clicks_base: b.clicks,
    google_position: Number((g.position || 0).toFixed(2)),
    cannibalization_status: cannib ? cannib.severity : 'OK',
    top_incident_score: cannib ? cannib.risk_score : 0,
    sitewide_overlap_status: sitewideOverlap ? sitewideOverlap.severity : 'OK',
    sitewide_overlap_score: sitewideOverlap ? sitewideOverlap.risk_score : 0,
    sitewide_overlap_type: sitewideOverlap ? sitewideOverlap.incident_type : '',
    sitewide_overlap_competitor: sitewideOverlap ? sitewideOverlap.competitor_url : ''
  };
};

const categoriesHealth = [...new Set(targetCategories)].map(classifyCategory);

// ----- Unknown query discovery -----
// Discovery is a SEPARATE review queue, never evidence for a cannibalization incident.
// Keep site-wide totals separate from monitored-200 contribution so the report cannot imply
// that all query impressions belong to a monitored category.

const classifyDiscoveryQuery = (query) => {
  const q = normalizeQuery(query);

  const primary = primaryQueryOwners[q];
  if (primary) {
    return {
      cluster: `Primary · ${primary.category}`,
      owner_url: primary.owner_url,
      confidence: 'HIGH',
      method: 'MASTER_PRIMARY',
      reason: 'Точное совпадение с primary_query из Master_Briefs; owner задан вручную в мастер-брифе.'
    };
  }

  // Model-specific branded queries are not auto-assigned to a category owner.
  const boosterBrand = /(^|\s)(booster|бустер|бостер)(\s|$)/i.test(q);
  const modelSpecific = /(pro\s*3|pro\s*2|\ba2\b|\bu1\b|\bm2\b|mini\s*2|mini\s*x|lightsaber|transformer|dp\s*s6|dp\s*pro\s*6|d5)/i.test(q);
  if (boosterBrand && modelSpecific) {
    return {
      cluster: '', owner_url: '', confidence: 'LOW', method: 'MODEL_QUERY',
      reason: 'Брендовый запрос конкретной модели: category owner автоматически не назначается.'
    };
  }

  const rules = [
    { cluster:'От целлюлита', owner:'/collection/massazhyory-ot-tsellyulita', markers:['целлюлит','антицеллюлит','похуден'] },
    { cluster:'Спорт / восстановление', owner:'/collection/dlya_sporta', markers:['спорт','спортсмен','трениров','восстановлен'] },
    { cluster:'Спина', owner:'/collection/massazhyory-dlya-spiny', markers:['спин','поясниц','лопат'] },
    { cluster:'Шея / ШВЗ', owner:'/collection/massazhyory-dlya-shei', markers:['шейн','шея','шеи','швз','воротников'] },
    { cluster:'Ноги / стопы', owner:'/collection/massazhyory-dlya-nog', markers:['ног','стоп','икр','бедр'] },
    { cluster:'Лицо / голова', owner:'/collection/massazhyory-dlya-litsa', markers:['лиц','голов','декольте'] },
    { cluster:'Плечи', owner:'/collection/perkussionnye-massazhyory-dlya-plech', markers:['плеч','дельт'] },
    { cluster:'Мощные', owner:'/collection/moschnye-massazhyory', markers:['мощн','глубок'] },
    { cluster:'Бюджетные', owner:'/collection/nedorogie-massazhyory', markers:['бюджет','недорог','дешев'] },
    { cluster:'Мини / компактные', owner:'/collection/kompaktnye-massazhyory', markers:['мини','компакт','дорож','поезд'] },
    { cluster:'Для дома', owner:'/collection/massazhyory-dlya-doma', markers:['для дома','домашн','семь'] },
    { cluster:'Профессиональные', owner:'/collection/professionalnye-massazhyory', markers:['профессионал','кабинет','массажист','мастер'] },
    { cluster:'Тело / мышцы', owner:'/collection/massazhyory-dlya-tela', markers:['тело','мышц'] },
    { cluster:'Booster', owner:'/collection/massazhyory-booster', markers:['booster','бустер','бостер'] }
  ];

  const matchMarker = (root) => {
    const esc = root.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    // Marker must start at a token boundary. This prevents "ног" matching inside "шейного".
    return new RegExp(`(^|[^а-яa-z0-9])${esc}[а-яa-z0-9-]*`, 'i').test(q);
  };
  const hits = [];
  for (const r of rules) {
    if (r.markers.some(matchMarker)) hits.push(r);
  }

  // Keep only owners that are actually in current Daily_Monitor 200 scope.
  const scopedHits = hits.filter(h => activeTargets.has(normalizeUrl(`https://boosterpro.ru${h.owner}`)));
  const uniqueOwners = [...new Set(scopedHits.map(h => h.owner))];

  if (uniqueOwners.length === 1) {
    const h = scopedHits.find(x => x.owner === uniqueOwners[0]);
    return {
      cluster: h.cluster,
      owner_url: normalizeUrl(`https://boosterpro.ru${h.owner}`),
      confidence: 'HIGH',
      method: 'RULE_MARKER',
      reason: `Однозначный маркер интента: ${h.markers.filter(matchMarker).join(', ')}.`
    };
  }
  if (uniqueOwners.length > 1) {
    return {
      cluster: '', owner_url: '', confidence: 'LOW', method: 'AMBIGUOUS',
      reason: `Запрос содержит маркеры нескольких monitored-интентов (${scopedHits.map(h => h.cluster).join(' / ')}); требуется ручная классификация.`
    };
  }

  return {
    cluster: '', owner_url: '', confidence: 'LOW', method: 'UNCLASSIFIED',
    reason: 'Нет однозначного зонального/коммерческого маркера для monitored-категорий; owner не угадывается автоматически.'
  };
};

