  if (d.relation === 'NOT_FOUND') return `${label}: BoosterPro вне TOP10`;
  const rank = Number(d.rank) > 0 ? `#${Math.round(Number(d.rank))}` : '';
  if (d.relation === 'OWNER') return `${label}: целевая страница ${rank}`.trim();
  const target = prettyUrlName(d.result_url);
