  const cur7 = Math.round(Number(x.competitor_impressions_7d||0));
  const prev7 = Math.round(Number(x.competitor_impressions_prev7||0));
  const c28 = prev28 > 0 ? (cur28-prev28)/prev28 : null;
  const c7 = prev7 > 0 ? (cur7-prev7)/prev7 : null;
  if (String(x.trend||'').toUpperCase()==='WORSENING' || (c28!==null && c7!==null && c28 >= 0.20 && c7 >= 0.30)) {
    return `Динамика ухудшается: у конкурирующей страницы показы выросли <b>${prev28} → ${cur28}</b> за 28 дней и <b>${prev7} → ${cur7}</b> за последние 7 дней.`;
  }
  if ((c28!==null && c28 <= -0.15) && (c7===null || c7 <= -0.20)) {
    return `Сейчас конфликт ослабевает: у конкурирующей страницы показы снизились <b>${prev28} → ${cur28}</b> за 28 дней и <b>${prev7} → ${cur7}</b> за последние 7 дней.`;
  }
  if (String(x.trend||'').toUpperCase()==='IMPROVING') {
    return `Динамика улучшается: у конкурирующей страницы сейчас <b>${cur28}</b> показов против <b>${prev28}</b> в предыдущие 28 дней.`;
  }
  return `По динамике резкого изменения нет: <b>${prev28} → ${cur28}</b> показов у конкурирующей страницы за 28 дней.`;
};

